    const log = (label, tone = 'muted') => ({
        p: 'log',
        op: 'push',
        item: { label, tone },
    });
    const drop = (lane, label, tone) => ({
        p: 'layers',
        op: 'push',
        lane,
        item: { label, tone },
    });
    const spotlight = (lane) => ({ p: 'layers', op: 'active', value: lane });
    const counter = (lane, n, text, tone) => ({
        p: 'layers',
        op: 'value',
        key: lane,
        value: n,
        label: text,
        tone,
    });
    const clock = (track, ms, tone) => ({
        p: 'race',
        op: 'value',
        key: track,
        value: ms,
        label: `${ms.toFixed(1).replace('.', ',')} ms`,
        tone,
    });
    const dbTrip = (track) => ({ p: 'race', op: 'push', lane: track, item: { label: 'db' } });
    function collector() {
        const steps = [];
        const push = (step) => {
            steps.push(Object.assign({ kind: 'INTERNAL' }, step));
        };
        return { steps, push };
    }
    function meters() {
        let plain = 0;
        let layered = 0;
        return {
            tick(ms, hitDb, tone) {
                plain += MS_DB;
                layered += ms;
                const ops = [dbTrip('plain'), clock('plain', plain), clock('layered', layered, tone)];
                if (hitDb)
                    ops.push(dbTrip('layered'));
                return ops;
            },
        };
    }
