    function collector() {
        const steps = [];
        const push = (id, title, detail, duration, ops, extra = {}) => {
            steps.push(Object.assign({ id, title, detail, kind: 'INTERNAL', duration, ops }, extra));
        };
        return { steps, push };
    }
    function buildBefore() {
        const { steps, push } = collector();
        push('query', { vi: 'Truy vấn bình thường nhất mà một API từng chạy', en: 'The most ordinary query an API ever runs' }, {
