    function collector() {
        const steps = [];
        const push = (id, title, detail, duration, ops, extra = {}) => {
            steps.push(Object.assign({ id, title, detail, kind: 'INTERNAL', duration, ops }, extra));
        };
        return { steps, push };
    }
    function buildPattern() {
